function Field({label,children,hint}:{label:string;children:ReactNode;hint?:string}){const id=useId(),control=isValidElement(children)&&typeof children.type==='string'&&['input','select','textarea'].includes(children.type);return <div className="field"><label id={id+'label'} htmlFor={control?id:undefined}>{label}</label>{control?cloneElement(children as ReactElement<any>,{id,'aria-describedby':hint?id+'hint':undefined}):<div role="group" aria-labelledby={id+'label'}>{children}</div>}{hint&&<small id={id+'hint'}>{hint}</small>}</div>}
