 {kind==='payments'&&<><div className="form-grid"><Field label="Дата оплаты"><input type="datetime-local" required value={d.date} onChange={e=>set('date',e.target.value)}/></Field><Field label="Сумма, ₽"><input autoFocus type="number" min="0.01" step="0.01" max="1000000" required value={d.amount/100} onChange={e=>set('amount',Math.round(Number(e.target.value)*100))}/></Field></div><div className="payment-preview"><span>Текущий баланс ученика</span><strong>{money(balance(data,d.studentId))}</strong><small>Оплата учитывается вручную. Деньги через приложение не переводятся.</small></div></>}
